def solve(x):
    if not x:
        return []
    result = []
    current_value = x[0]
    current_count = 1
    for value in x[1:]:
        if value == current_value:
            current_count += 1
        else:
            result.append([current_value, current_count])
            current_value = value
            current_count = 1
    result.append([current_value, current_count])
    return result
